from pathlib import Path
import re, json

p=Path('index.html')
s=p.read_text(encoding='utf-8')

m=re.search(r'const IMAGES=(\{.*?\});\s*const LOGO="(data:image/png;base64,[^"]+)";',s,re.S)
if not m:
    raise SystemExit('ERROR: V20 IMAGES/LOGO block not found')
imgs=json.loads(m.group(1))
logo=m.group(2)

def I(key):
    return imgs.get(key) or imgs.get('hero') or ''

